<style>
.sf-showcase{--sf-ink:#edf2ff;--sf-muted:#a9b4ce;--sf-surface:#131b30;--sf-border:#ffffff1a;padding:95px 0;color:var(--sf-ink);position:relative}html.light-mode .sf-showcase{--sf-ink:#17213a;--sf-muted:#64718b;--sf-surface:#fff;--sf-border:#17213a17}.sf-container{max-width:1280px;padding:0 40px;margin:auto}.sf-heading{text-align:center;max-width:760px;margin:0 auto 35px}.sf-heading>span{font-size:11px;font-weight:700;letter-spacing:.15em;text-transform:uppercase;color:var(--sf-muted)}.sf-heading h2{font-size:clamp(30px,3.7vw,48px);font-weight:800;line-height:1.15;letter-spacing:-.035em;margin:14px 0 18px}.sf-heading p{font-size:16px;line-height:1.7;color:var(--sf-muted)}.sf-total{font-size:11px;font-weight:600;display:inline-flex;border:1px solid var(--sf-border);padding:7px 12px;border-radius:20px;margin-top:18px}
.sf-toolbar{display:flex;gap:14px;align-items:center;justify-content:space-between;flex-wrap:wrap;margin:28px 0 12px}.sf-filters{display:flex;gap:7px;flex-wrap:wrap}.sf-filters button{font-size:11px;padding:10px 12px;border-radius:12px;border:1px solid var(--sf-border);color:var(--sf-muted);background:var(--sf-surface)!important}.sf-filters button[aria-pressed=true]{background:#5363ed!important;color:#fff;border-color:#5363ed}.sf-filters span{font-size:9px;opacity:.75;margin-left:4px}.sf-search{border:1px solid var(--sf-border);border-radius:12px;padding:10px 13px;display:flex;gap:10px;align-items:center;color:var(--sf-muted);background:var(--sf-surface);font-size:12px}.sf-search input{width:170px;background:transparent!important;border:0!important;outline:none;color:var(--sf-ink)!important;font-size:12px!important;padding:0!important}.sf-results{font-size:11px;color:var(--sf-muted);margin:0 0 16px}
.sf-layout{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);gap:26px;align-items:start}.sf-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;max-height:760px;overflow-y:auto;padding:3px 6px 12px 3px;scrollbar-width:thin;scrollbar-color:#7785bd44 transparent}.sf-card{position:relative;display:flex;flex-direction:column;text-align:left;padding:18px;min-height:205px;gap:9px;border-radius:20px;border:1px solid var(--sf-border);background:var(--sf-surface)!important;color:var(--sf-ink)!important;transition:border-color .25s,box-shadow .25s,transform .25s;overflow:hidden}.sf-card:hover,.sf-card:focus-visible{transform:translateY(-2px);border-color:var(--sf-accent);box-shadow:0 10px 25px color-mix(in srgb,var(--sf-accent) 12%,transparent)}.sf-card.sf-selected{border-color:var(--sf-accent);background:linear-gradient(140deg,color-mix(in srgb,var(--sf-accent) 8%,transparent),transparent),var(--sf-surface)!important;box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--sf-accent) 25%,transparent)}.sf-card-art{width:70px;height:52px;display:block;filter:drop-shadow(0 5px 5px #273c5b13)}.sf-art{width:100%;height:100%;overflow:visible}.sf-card>strong{font-size:14px;line-height:1.4}.sf-card-desc{font-size:11px;color:var(--sf-muted);line-height:1.65}.sf-card-hint{font-size:10px;color:var(--sf-accent);margin-top:auto;padding-top:3px;display:flex;align-items:center;gap:7px}
.sf-preview{position:sticky;top:100px;border:1px solid var(--sf-border);border-radius:25px;padding:24px;background:radial-gradient(ellipse at top right,color-mix(in srgb,var(--sf-accent) 8%,transparent),transparent 65%),var(--sf-surface);box-shadow:0 18px 55px #17223b0d;min-width:0}.sf-preview-top{display:flex;align-items:center;justify-content:space-between;color:var(--sf-muted);font-size:10px}.sf-preview-top button{display:grid;place-items:center;width:28px;height:28px;border-radius:50%;border:1px solid var(--sf-border);background:transparent!important;color:var(--sf-muted);font-size:10px}.sf-preview h3{font-size:25px;font-weight:750;line-height:1.3;margin:8px 0 10px;letter-spacing:-.025em}.sf-preview>p{font-size:12px;line-height:1.7;color:var(--sf-muted)}.sf-preview-scene{padding-top:20px;min-width:0}.sf-preview-scene .lts{height:345px;min-height:280px;border-radius:23px;max-width:330px;margin:auto;border-width:7px;border-color:#222a41;box-shadow:0 16px 30px #18244a12;animation:sf-preview-in .35s ease-out both}.sf-preview-caption{text-align:center;font-size:9px!important;margin-top:12px!important}.sf-use{padding:15px 0;border-top:1px solid var(--sf-border);margin-top:15px}.sf-use>strong{font-size:10px;color:var(--sf-accent);text-transform:uppercase;letter-spacing:.06em}.sf-use p{font-size:12px;color:var(--sf-muted);line-height:1.65;margin-top:6px}.sf-preview-actions{display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin-top:15px}.sf-create,.sf-demo{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:12px 16px;border-radius:12px;font-size:12px;font-weight:650}.sf-create{background:#5363ed;color:#fff!important}.sf-demo{border:1px solid var(--sf-border);color:var(--sf-ink)}.sf-empty{grid-column:1/-1;text-align:center;padding:60px 15px;display:grid;justify-items:center;gap:12px;color:var(--sf-muted);font-size:13px}.sf-empty button{color:#7b8aef;border:1px solid var(--sf-border);border-radius:10px;padding:10px 15px;background:transparent!important}.sf-showcase [hidden]{display:none!important}.sf-showcase button:focus-visible,.sf-showcase a:focus-visible,.sf-search:focus-within{outline:2px solid #818cf8;outline-offset:3px}
.sf-selected .sf-art-bob,.sf-card:hover .sf-art-bob{animation:sf-bob 4.5s ease-in-out infinite}.sf-selected .sf-scan{animation:sf-scan 2.8s ease-in-out infinite}.sf-selected .sf-download{animation:sf-download 2.5s ease-in-out infinite}.sf-selected .sf-draw{stroke-dasharray:80;animation:sf-draw 3.5s ease-in-out infinite}.sf-selected .sf-chat-dots{animation:sf-dots 2s ease-in-out infinite}.sf-selected .sf-page-blocks,.sf-selected .sf-product{animation:sf-blocks 3.5s ease-in-out infinite}@keyframes sf-bob{50%{transform:translateY(-3px)}}@keyframes sf-scan{0%,100%{transform:translateY(-25px);opacity:.2}50%{transform:translateY(35px);opacity:1}}@keyframes sf-download{50%{transform:translateY(5px)}}@keyframes sf-draw{0%,15%{stroke-dashoffset:80}45%,90%{stroke-dashoffset:0}100%{stroke-dashoffset:80}}@keyframes sf-dots{50%{opacity:.35}}@keyframes sf-blocks{0%,100%{opacity:.75}50%{opacity:1;transform:translateY(-2px)}}@keyframes sf-preview-in{from{opacity:.5;transform:translateY(5px)}to{opacity:1;transform:translateY(0)}}
.sf-paused *,.sf-paused *:before,.sf-paused *:after{animation-play-state:paused!important}
@media(max-width:1050px){.sf-layout{gap:18px}.sf-container{padding-inline:30px}.sf-filters button{padding:9px;font-size:10px}.sf-card{padding:15px}.sf-preview{padding:20px}}
@media(max-width:760px){.sf-container{padding-inline:22px}.sf-showcase{padding:65px 0}.sf-layout{display:block}.sf-list{max-height:none;overflow:visible;padding:2px}.sf-preview{position:relative;top:auto;grid-column:1/-1;margin:4px 0 8px;width:100%}.sf-toolbar{gap:14px}.sf-search{width:100%}.sf-search input{width:100%}.sf-card{min-height:190px}.sf-card>strong{font-size:13px}.sf-card-desc{font-size:10px}.sf-heading h2{font-size:32px}.sf-heading p{font-size:14px}.sf-preview-scene .lts{height:310px}.sf-filters{gap:6px}}
@media(prefers-reduced-motion:reduce){.sf-showcase *,.sf-showcase *:before,.sf-showcase *:after{animation:none!important;transition:none!important;transform:none!important}.sf-draw{stroke-dashoffset:0!important}.sf-showcase .lts *{opacity:1!important}}
</style>

<style>.sf-preview[data-art=qr] .lts,.sf-preview[data-art=file] .lts,.sf-preview[data-art=link] .lts{max-width:none;border-width:1px;border-color:var(--sf-border);border-radius:18px;height:310px}.sf-paused .lts *{animation:none!important;opacity:1!important;transform:none!important}</style>
<style>.sf-preview .lts{color:var(--sf-ink);font-size:12px}.sf-preview .lts-btn.lts-solid{background:var(--a)!important;border-color:transparent!important;color:#fff!important}</style>
